import React, { useState, useEffect, useRef, useCallback } from 'react';
import io from 'socket.io-client';
import { Avatar3D } from '../components/Avatar3D';
import { DraggableUserVideo } from '../components/DraggableUserVideo';
import { ShareModal } from '../components/ShareModal';
import { VideoPlayerModal } from '../components/VideoPlayerModal';
import { SidePanel } from '../components/SidePanel';
import { CallControls } from '../components/CallControls';
import { useVoiceInput } from '../hooks/useVoiceInput';
import { sendChatMessage } from '../utils/api';
import toast, { Toaster } from 'react-hot-toast';

const socket = io('http://localhost:8000', {
  transports: ['websocket'],
  reconnection: true,
  reconnectionAttempts: 5,
  reconnectionDelay: 1000,
});

// ✅ CLEAN TEXT
const cleanTextForSpeech = (text) => {
  if (!text) return '';
  return text
    .replace(/[\u{1F300}-\u{1F9FF}]|[\u{2600}-\u{26FF}]|[\u{2700}-\u{27BF}]/gu, '')
    .replace(/[👋👍❤️🎉😂🔥💪✨🌟💯🎯🎊🎈🎨📝💬👥]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

export const VideoCallPage = ({ companion, roomId, userId, onEndCall }) => {
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(false);
  const [mediaStream, setMediaStream] = useState(null);
  const [isCameraLoading, setIsCameraLoading] = useState(true);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState(null);
  const [callTime, setCallTime] = useState(0);
  const [isRecording, setIsRecording] = useState(false);
  const [isShareModalOpen, setShareModalOpen] = useState(false);
  const [activePanel, setActivePanel] = useState('chat');
  const [isMenuOpen, setMenuOpen] = useState(false);
  const [reactions, setReactions] = useState([]);
  const [playingVideoId, setPlayingVideoId] = useState(null);
  const [messages, setMessages] = useState([]);
  const [isAISpeaking, setIsAISpeaking] = useState(false);
  const [currentSpeakingText, setCurrentSpeakingText] = useState('');
  const [hasPlayedIntro, setHasPlayedIntro] = useState(false);
  const [customAnimation, setCustomAnimation] = useState(null);
  const [participants, setParticipants] = useState([]);
  const [remoteStreams, setRemoteStreams] = useState({});

  const peerConnections = useRef({});
  const hasJoinedRoom = useRef(false);
  const userVideoRef = useRef(null);
  const screenVideoRef = useRef(null);
  const synth = useRef(null);
  const mediaStreamRef = useRef(null);
  const screenStreamRef = useRef(null);
  const timerRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const recordedChunksRef = useRef([]);
  const currentUtteranceRef = useRef(null);
  const isCurrentlySpeakingRef = useRef(false);

  const getCompanionId = useCallback(() => {
    return companion?.id || 'omkar_ai';
  }, [companion]);

  const handlePlayAnimation = useCallback((animationId) => {
    console.log('🎮 Playing animation:', animationId);
    setCustomAnimation(animationId);
    setTimeout(() => setCustomAnimation(null), 8000);
  }, []);

  // ✅ COMPLETE STOP
  const handleStopAI = useCallback(() => {
    console.log('⏹️ STOPPING AI');
    
    isCurrentlySpeakingRef.current = false;
    
    if (window.speechSynthesis) {
      window.speechSynthesis.cancel();
    }
    
    if (currentUtteranceRef.current) {
      currentUtteranceRef.current = null;
    }
    
    setIsAISpeaking(false);
    setCurrentSpeakingText('');
    
    console.log('✅ AI STOPPED');
  }, []);

  // ✅ SIMPLE TTS - NO VOICE CACHING
  const speakWithVoice = useCallback((text, isFemale) => {
    return new Promise((resolve, reject) => {
      const cleanedText = cleanTextForSpeech(text);
      if (!cleanedText) {
        resolve();
        return;
      }

      console.log(`🗣️ Speaking with ${isFemale ? 'FEMALE' : 'MALE'} voice`);
      
      if (window.speechSynthesis) {
        window.speechSynthesis.cancel();
      }
      
      const utterance = new SpeechSynthesisUtterance(cleanedText);
      
      // ✅ Get voices safely
      try {
        const voices = window.speechSynthesis.getVoices();
        if (voices && voices.length > 0) {
          // Simple voice selection - use index 0 for male, 1 for female
          const voiceIndex = isFemale ? (voices.length > 1 ? 1 : 0) : 0;
          utterance.voice = voices[voiceIndex];
          console.log('✅ Using voice:', voices[voiceIndex]?.name);
        }
      } catch (err) {
        console.warn('⚠️ Could not set voice, using default');
      }
      
      utterance.rate = 0.95;
      utterance.pitch = 1.0;
      utterance.volume = 1.0;
      utterance.lang = 'en-US';

      utterance.onstart = () => {
        isCurrentlySpeakingRef.current = true;
        setIsAISpeaking(true);
        setCurrentSpeakingText(cleanedText);
      };

      utterance.onend = () => {
        if (isCurrentlySpeakingRef.current) {
          isCurrentlySpeakingRef.current = false;
          setIsAISpeaking(false);
          setCurrentSpeakingText('');
          currentUtteranceRef.current = null;
          resolve();
        }
      };

      utterance.onerror = (err) => {
        console.error('❌ TTS error:', err);
        isCurrentlySpeakingRef.current = false;
        setIsAISpeaking(false);
        setCurrentSpeakingText('');
        currentUtteranceRef.current = null;
        reject(err);
      };

      currentUtteranceRef.current = utterance;
      
      if (window.speechSynthesis) {
        setTimeout(() => {
          window.speechSynthesis.speak(utterance);
        }, 100);
      }
    });
  }, []);

  // ✅ PLAY AUDIO
  const playAudio = useCallback(
    async (audioUrl, fullText) => {
      try {
        if (isCurrentlySpeakingRef.current) {
          handleStopAI();
          await new Promise(resolve => setTimeout(resolve, 200));
        }

        const isFemale = getCompanionId() === 'priya_biology';
        console.log(`🎭 Character: ${isFemale ? 'PRIYA (Female)' : 'OMKAR (Male)'}`);
        
        isCurrentlySpeakingRef.current = true;
        await speakWithVoice(fullText, isFemale);
        
      } catch (error) {
        console.error('❌ Error playing audio:', error);
        isCurrentlySpeakingRef.current = false;
        setIsAISpeaking(false);
        setCurrentSpeakingText('');
      }
    },
    [getCompanionId, handleStopAI, speakWithVoice]
  );

  const getMedia = useCallback(
    async (opts = { video: true, audio: true }) => {
      setIsCameraLoading(true);
      try {
        const stream = await navigator.mediaDevices.getUserMedia(opts);
        setMediaStream(stream);
        mediaStreamRef.current = stream;

        if (userVideoRef.current && !isVideoOff) {
          userVideoRef.current.srcObject = stream;
          userVideoRef.current.play().catch(() => {});
        }

        return stream;
      } catch (err) {
        console.error('❌ Error accessing media:', err);
        toast.error('Could not access camera/microphone');
        return null;
      } finally {
        setIsCameraLoading(false);
      }
    },
    [isVideoOff]
  );

  const createPeerConnection = useCallback((targetUserId, stream) => {
    const configuration = {
      iceServers: [
        { urls: 'stun:stun.l.google.com:19302' },
      ],
    };

    const pc = new RTCPeerConnection(configuration);
    peerConnections.current[targetUserId] = pc;

    if (stream) {
      stream.getTracks().forEach((track) => {
        pc.addTrack(track, stream);
      });
    }

    pc.ontrack = (event) => {
      setRemoteStreams((prev) => ({
        ...prev,
        [targetUserId]: event.streams[0],
      }));
    };

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        socket.emit('ice-candidate', {
          roomId,
          candidate: event.candidate,
          targetUserId,
          fromUserId: userId,
        });
      }
    };

    return pc;
  }, [roomId, userId]);

  useEffect(() => {
    let mounted = true;

    const initWebRTC = async () => {
      const stream = await getMedia({ video: true, audio: true });
      if (!stream || !mounted) return;

      await new Promise(resolve => setTimeout(resolve, 500));

      if (!hasJoinedRoom.current) {
        hasJoinedRoom.current = true;
        socket.emit('join-room', { roomId, userId, companionId: companion?.id });
      }

      socket.on('user-joined', (data) => {
        toast.success(`${data.userId.substring(0, 15)}... joined`, { duration: 2000 });
        setParticipants((prev) => {
          if (prev.some(p => p.userId === data.userId)) return prev;
          return [...prev, { userId: data.userId, joinedAt: Date.now() }];
        });

        const pc = createPeerConnection(data.userId, stream);
        pc.createOffer()
          .then((offer) => pc.setLocalDescription(offer))
          .then(() => {
            socket.emit('offer', {
              roomId,
              offer: pc.localDescription,
              targetUserId: data.userId,
              fromUserId: userId,
            });
          });
      });

      socket.on('existing-users', (users) => {
        setParticipants(users.map(u => ({ userId: u, joinedAt: Date.now() })));
      });

      socket.on('user-left', (data) => {
        setParticipants((prev) => prev.filter((p) => p.userId !== data.userId));
        setRemoteStreams((prev) => {
          const newStreams = { ...prev };
          delete newStreams[data.userId];
          return newStreams;
        });

        if (peerConnections.current[data.userId]) {
          peerConnections.current[data.userId].close();
          delete peerConnections.current[data.userId];
        }
      });

      socket.on('offer', async (data) => {
        const { offer, fromUserId } = data;
        const pc = createPeerConnection(fromUserId, stream);
        await pc.setRemoteDescription(new RTCSessionDescription(offer));
        const answer = await pc.createAnswer();
        await pc.setLocalDescription(answer);
        socket.emit('answer', {
          roomId,
          answer,
          targetUserId: fromUserId,
          fromUserId: userId,
        });
      });

      socket.on('answer', async (data) => {
        const { answer, fromUserId } = data;
        const pc = peerConnections.current[fromUserId];
        if (pc && pc.signalingState === 'have-local-offer') {
          await pc.setRemoteDescription(new RTCSessionDescription(answer));
        }
      });

      socket.on('ice-candidate', async (data) => {
        const { candidate, fromUserId } = data;
        const pc = peerConnections.current[fromUserId];
        if (pc && pc.remoteDescription) {
          try {
            await pc.addIceCandidate(new RTCIceCandidate(candidate));
          } catch (err) {
            console.error('ICE error:', err);
          }
        }
      });

      socket.on('chat-message', (data) => {
        const newMessage = {
          sender: data.sender,
          text: data.message,
          timestamp: data.timestamp,
          userId: data.userId,
        };
        
        setMessages((prev) => {
          if (prev.some(m => m.timestamp === data.timestamp && m.userId === data.userId)) {
            return prev;
          }
          return [...prev, newMessage];
        });
      });
    };

    initWebRTC();

    timerRef.current = setInterval(() => setCallTime((t) => t + 1), 1000);

    return () => {
      mounted = false;
      hasJoinedRoom.current = false;
      clearInterval(timerRef.current);
      
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach((t) => t.stop());
      }
      
      if (window.speechSynthesis) {
        window.speechSynthesis.cancel();
      }

      Object.values(peerConnections.current).forEach((pc) => {
        try { pc.close(); } catch (e) {}
      });
      
      socket.emit('leave-room', { roomId, userId });
      socket.off('user-joined');
      socket.off('user-left');
      socket.off('existing-users');
      socket.off('offer');
      socket.off('answer');
      socket.off('ice-candidate');
      socket.off('chat-message');
    };
  }, [roomId, userId, companion?.id, getMedia, createPeerConnection]);

  useEffect(() => {
    if (!mediaStream) return;

    mediaStream.getAudioTracks().forEach((track) => {
      track.enabled = !isMuted;
    });

    mediaStream.getVideoTracks().forEach((track) => {
      track.enabled = !isVideoOff;
    });
  }, [isMuted, isVideoOff, mediaStream]);

  const toggleScreenShare = async () => {
    if (isScreenSharing) {
      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach((track) => track.stop());
      }
      setScreenStream(null);
      setIsScreenSharing(false);
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        screenStreamRef.current = stream;
        setIsScreenSharing(true);

        stream.getVideoTracks()[0].onended = () => {
          setScreenStream(null);
          screenStreamRef.current = null;
          setIsScreenSharing(false);
        };
      } catch (err) {
        console.error('Screen share error:', err);
      }
    }
  };

  const sendReaction = (emoji) => {
    const newReaction = { id: Date.now(), emoji, left: Math.random() * 80 + 10 };
    setReactions((prev) => [...prev, newReaction]);
    setTimeout(() => setReactions((prev) => prev.filter((r) => r.id !== newReaction.id)), 4000);
  };

  const handleIntroComplete = useCallback(
    async (introData) => {
      if (!hasPlayedIntro && introData) {
        setHasPlayedIntro(true);

        setTimeout(async () => {
          const introMsg = {
            sender: 'ai',
            text: introData.message,
            timestamp: new Date().toISOString(),
            source: 'intro',
          };

          setMessages([introMsg]);
          await playAudio(null, introData.message);
        }, 1500);
      }
    },
    [hasPlayedIntro, playAudio]
  );

  const handleVoiceResult = useCallback(
    async (transcript) => {
      if (!transcript?.trim()) return;

      const userMessage = {
        sender: 'user',
        text: transcript,
        timestamp: new Date().toISOString(),
        userId: userId,
      };
      setMessages((prev) => [...prev, userMessage]);

      socket.emit('chat-message', {
        roomId,
        userId,
        message: transcript,
        sender: 'user',
        timestamp: userMessage.timestamp,
      });

      try {
        const chatHistory = messages.slice(-10).map(m => ({
          role: m.sender === 'user' ? 'user' : 'assistant',
          content: m.text
        }));

        const response = await sendChatMessage(
          transcript,
          companion.id,
          roomId,
          companion.subject || 'General',
          0,
          chatHistory
        );

        const aiTimestamp = new Date().toISOString();
        const aiMessage = {
          sender: 'ai',
          text: response.text || response.message || 'I received your message.',
          timestamp: aiTimestamp,
          source: response.source || 'gemini',
          userId: companion.id,
        };

        setMessages((prev) => [...prev, aiMessage]);
        
        socket.emit('chat-message', {
          roomId,
          userId: companion.id,
          message: aiMessage.text,
          sender: 'ai',
          timestamp: aiTimestamp,
        });
        
        await playAudio(response.audioUrl, aiMessage.text);
      } catch (error) {
        console.error('Error in voice chat:', error);
      }
    },
    [companion, roomId, playAudio, userId, messages]
  );

  const { isListening, startListening, stopListening } = useVoiceInput({
    onResult: handleVoiceResult,
    language: 'en-US',
  });

  const handleSendMessage = async (text) => {
    if (!text?.trim()) return;

    const timestamp = new Date().toISOString();
    const userMessage = {
      sender: 'user',
      text,
      timestamp,
      userId: userId,
    };
    
    setMessages((prev) => [...prev, userMessage]);

    socket.emit('chat-message', {
      roomId,
      userId,
      message: text,
      sender: 'user',
      timestamp,
    });

    try {
      const chatHistory = messages.slice(-10).map(m => ({
        role: m.sender === 'user' ? 'user' : 'assistant',
        content: m.text
      }));

      const response = await sendChatMessage(
        text,
        companion.id,
        roomId,
        companion.subject || 'General',
        0,
        chatHistory
      );

      const aiTimestamp = new Date().toISOString();
      const aiMessage = {
        sender: 'ai',
        text: response.text || response.message || 'I received your message.',
        timestamp: aiTimestamp,
        source: response.source || 'gemini',
        userId: companion.id,
      };
      
      setMessages((prev) => [...prev, aiMessage]);
      
      socket.emit('chat-message', {
        roomId,
        userId: companion.id,
        message: aiMessage.text,
        sender: 'ai',
        timestamp: aiTimestamp,
      });
      
      await playAudio(response.audioUrl, aiMessage.text);
    } catch (error) {
      console.error('Error sending message:', error);
    }
  };

  const formatTime = (seconds) =>
    `${Math.floor(seconds / 60).toString().padStart(2, '0')}:${(seconds % 60).toString().padStart(2, '0')}`;

  return (
    <>
      <Toaster position="top-center" />
      
      <div className="relative w-full h-screen bg-gradient-to-br from-gray-900 via-purple-900 to-indigo-900 overflow-hidden flex">
        <div className="flex-1 relative flex items-center justify-center">
          <Avatar3D
            avatarMode={customAnimation || (isAISpeaking ? 'talk' : 'idle')}
            companionId={companion?.id || 'omkar_ai'}
            isAISpeaking={isAISpeaking}
            currentText={currentSpeakingText}
            onIntroComplete={handleIntroComplete}
          />

          <div className="absolute top-4 left-4 bg-black/50 backdrop-blur-sm px-4 py-2 rounded-lg text-white flex items-center gap-2 z-10">
            <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
            <span className="font-mono">{formatTime(callTime)}</span>
          </div>

          <div className="absolute top-4 right-4 z-10">
            <button
              onClick={() => setMenuOpen(!isMenuOpen)}
              className="p-3 bg-gray-800/80 backdrop-blur-sm rounded-full hover:bg-gray-700 transition-colors"
            >
              <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20">
                <circle cx="10" cy="5" r="1.5"/>
                <circle cx="10" cy="10" r="1.5"/>
                <circle cx="10" cy="15" r="1.5"/>
              </svg>
            </button>

            {isMenuOpen && (
              <div className="absolute right-0 top-full mt-2 w-56 bg-gray-800 rounded-lg shadow-2xl border border-gray-700 py-2">
                <button onClick={() => { handlePlayAnimation('walk'); setMenuOpen(false); }}
                  className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700">🏃 Walk</button>
                <button onClick={() => { handlePlayAnimation('dance'); setMenuOpen(false); }}
                  className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700">💃 Dance</button>
                <button onClick={() => { handlePlayAnimation('jump'); setMenuOpen(false); }}
                  className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700">🦘 Jump</button>
              </div>
            )}
          </div>

          <DraggableUserVideo
            videoRef={userVideoRef}
            userId={userId}
            isMuted={isMuted}
            isVideoOff={isVideoOff}
            isCameraLoading={isCameraLoading}
          />

          {Object.entries(remoteStreams).map(([remoteUserId, stream], index) => (
            <RemoteUserVideo
              key={remoteUserId}
              stream={stream}
              userId={remoteUserId}
              index={index}
            />
          ))}

          {isScreenSharing && screenStream && (
            <div className="absolute top-20 left-4 w-64 h-48 bg-black rounded-lg overflow-hidden border-2 border-green-500 shadow-2xl z-10">
              <video ref={screenVideoRef} autoPlay playsInline className="w-full h-full object-contain" />
              <div className="absolute top-2 left-2 bg-green-600 px-2 py-1 rounded text-xs text-white">
                Sharing Screen
              </div>
            </div>
          )}

          {reactions.map((r) => (
            <div key={r.id} className="absolute bottom-32 text-4xl animate-bounce-up pointer-events-none z-10"
              style={{ left: `${r.left}%` }}>{r.emoji}</div>
          ))}

          <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 z-20">
            <CallControls
              isMuted={isMuted}
              setIsMuted={setIsMuted}
              isVideoOff={isVideoOff}
              setIsVideoOff={setIsVideoOff}
              isScreenSharing={isScreenSharing}
              toggleScreenShare={toggleScreenShare}
              sendReaction={sendReaction}
              onEndCall={onEndCall}
            />
          </div>
        </div>

        <div className="w-[30%] border-l border-gray-700 bg-gray-900">
          <SidePanel
            activePanel={activePanel}
            setActivePanel={setActivePanel}
            messages={messages}
            onSendMessage={handleSendMessage}
            roomId={roomId}
            companion={companion}
            userId={userId}
            onStopAI={handleStopAI}
            startListening={startListening}
            stopListening={stopListening}
            isListening={isListening}
            participants={[
              { userId: companion?.name || 'AI Tutor', role: 'AI', isOnline: true },
              { userId: userId.substring(0, 12) + '...', role: 'You (Host)', isOnline: true },
              ...participants.map(p => ({ 
                userId: p.userId.substring(0, 12) + '...', 
                role: 'Participant', 
                isOnline: true 
              }))
            ]}
          />
        </div>
      </div>

      {isShareModalOpen && (
        <ShareModal roomId={roomId} onClose={() => setShareModalOpen(false)} />
      )}

      {playingVideoId && (
        <VideoPlayerModal
          videoId={playingVideoId}
          onClose={() => setPlayingVideoId(null)}
        />
      )}
    </>
  );
};

const RemoteUserVideo = ({ stream, userId, index }) => {
  const videoRef = useRef(null);
  const audioRef = useRef(null);

  useEffect(() => {
    if (videoRef.current && stream) {
      videoRef.current.srcObject = stream;
      videoRef.current.play().catch(() => {});
    }
    
    if (audioRef.current && stream) {
      audioRef.current.srcObject = stream;
      audioRef.current.play().catch(() => {});
    }
  }, [stream]);

  return (
    <div
      className="absolute w-48 h-36 bg-black rounded-lg overflow-hidden border-2 border-blue-500 shadow-2xl z-10"
      style={{
        bottom: `${140 + index * 160}px`,
        right: '20px',
      }}
    >
      <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
      <audio ref={audioRef} autoPlay />
      
      <div className="absolute bottom-2 left-2 bg-black/70 px-2 py-1 rounded text-xs text-white">
        {userId.substring(0, 8)}...
      </div>
    </div>
  );
};
